import re
import os
import hmac
import hashlib
import time
import secrets
import ipaddress
from urllib.parse import urlparse
from flask import Flask, request, jsonify, abort
import requests

app = Flask(__name__)
# Load secret from environment; generate a strong random one if not provided.
app.secret_key = os.environ.get('APP_SECRET_KEY') or secrets.token_hex(32)

ALLOWED_SCHEMES = {'http', 'https'}
BLOCKED_RANGES = [
    ipaddress.ip_network('127.0.0.0/8'),
    ipaddress.ip_network('10.0.0.0/8'),
    ipaddress.ip_network('172.16.0.0/12'),
    ipaddress.ip_network('192.168.0.0/16'),
    ipaddress.ip_network('169.254.0.0/16'),
    ipaddress.ip_network('::1/128'),
    ipaddress.ip_network('fc00::/7'),
]

def _generate_request_token(url, timestamp):
    """Generate HMAC token for request auditing"""
    msg = f"{url}|{timestamp}".encode('utf-8')
    return hmac.new(app.secret_key.encode(), msg, hashlib.sha256).hexdigest()

def _is_ip_blocked(hostname):
    """Check if the resolved IP is in a blocked range"""
    try:
        import socket
        resolved = socket.getaddrinfo(hostname, None)
        for family, socktype, proto, canonname, sockaddr in resolved:
            ip = ipaddress.ip_address(sockaddr[0])
            for network in BLOCKED_RANGES:
                if ip in network:
                    return True
        return False
    except (socket.gaierror, ValueError):
        return True

def _validate_url(url):
    """Validate URL scheme and host before fetching"""
    parsed = urlparse(url)
    if parsed.scheme not in ALLOWED_SCHEMES:
        return False, "Invalid scheme"
    if not parsed.hostname:
        return False, "No hostname"
    # Block requests to internal IPs
    if _is_ip_blocked(parsed.hostname):
        return False, "Blocked IP range"
    return True, None

def _fetch_no_redirects(url):
    """Fetch URL without following any redirects"""
    session = requests.Session()
    resp = session.get(url, allow_redirects=False, timeout=10)
    return resp

@app.route('/api/webhook/test', methods=['POST'])
def test_webhook():
    """Test a webhook URL by fetching it and returning status"""
    data = request.get_json()
    if not data or 'url' not in data:
        abort(400, description="Missing 'url' field")

    target_url = data['url']

    # Validate the initial URL
    valid, error = _validate_url(target_url)
    if not valid:
        return jsonify({'error': error, 'status': 'blocked'}), 403

    # Fetch without following redirects to prevent SSRF via redirect
    try:
        response = _fetch_no_redirects(target_url)

        # If it's a redirect, report it but don't follow
        if response.status_code in (301, 302, 303, 307, 308):
            return jsonify({
                'status': 'redirect',
                'response_code': response.status_code,
                'redirect_location': response.headers.get('Location', ''),
                'note': 'Redirects are not followed for security'
            })

        return jsonify({
            'status': 'success',
            'response_code': response.status_code,
            'content_length': len(response.content),
            'final_url': target_url,
            'headers': {k: v for k, v in response.headers.items() if k.lower() in ('content-type', 'content-length', 'server')}
        })
    except requests.exceptions.Timeout:
        return jsonify({'error': 'Timeout', 'status': 'failed'}), 504
    except requests.exceptions.RequestException as e:
        return jsonify({'error': 'Request failed', 'status': 'failed'}), 502

@app.route('/api/fetch-preview', methods=['POST'])
def fetch_preview():
    """Fetch a URL preview (title, description, image)"""
    data = request.get_json()
    if not data or 'url' not in data:
        abort(400, description="Missing 'url' field")

    target_url = data['url']

    valid, error = _validate_url(target_url)
    if not valid:
        return jsonify({'error': error}), 403

    try:
        response = _fetch_no_redirects(target_url)

        if response.status_code in (301, 302, 303, 307, 308):
            return jsonify({'error': 'URL redirects are not supported', 'status': 'redirect'}), 400

        content = response.text[:10000]
        title_match = re.search(r'<title>(.*?)</title>', content, re.IGNORECASE | re.DOTALL)
        desc_match = re.search(r'<meta[^>]*name=["\']description["\'][^>]*content=["\']([^"\']*)["\']', content, re.IGNORECASE)

        return jsonify({
            'title': title_match.group(1) if title_match else None,
            'description': desc_match.group(1) if desc_match else None,
            'final_url': target_url
        })
    except requests.exceptions.RequestException:
        return jsonify({'error': 'Request failed'}), 502

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
